});

describe("mergeLabels happy path", () => {
  it("moves source to target, once per issue, including archived issues", async () => {
    const { source, target } = await seedPair(north, "happy");
    const other = await labelService.createLabel(north.actors.admin, {
      orgId: north.org.id,
      name: "happy-other",
      color: "#0000ff",
      description: null,
    });

    const onlySource = await makeIssue(north, "only source", [source.id]);
    const both = await makeIssue(north, "both", [source.id, target.id, other.id]);
    const onlyTarget = await makeIssue(north, "only target", [target.id]);
    const untouched = await makeIssue(north, "untouched", [other.id]);
    const archivedSource = await makeIssue(north, "archived source", [source.id]);
    await issueService.archiveIssue(north.actors.member, north.org.id, archivedSource.id);

    const before = (await labelRepo.findLabel(north.org.id, target.id)) as IssueLabel;

    const result = await labelService.mergeLabels(north.actors.admin, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });

    expect(result.issuesRelabelled).toBe(3);
    expect(result.label).toEqual(before);
    expect(result.label.id).toBe(target.id);

    expect(labelIdsOnIssue(onlySource.id)).toEqual([target.id]);
    expect(labelIdsOnIssue(both.id).sort()).toEqual([target.id, other.id].sort());
    expect(joinRowsFor(both.id, target.id)).toBe(1);
    expect(labelIdsOnIssue(onlyTarget.id)).toEqual([target.id]);
    expect(labelIdsOnIssue(untouched.id)).toEqual([other.id]);
    expect(labelIdsOnIssue(archivedSource.id)).toEqual([target.id]);

    await expect(labelRepo.findLabel(north.org.id, source.id)).resolves.toBeNull();
    const after = await labelRepo.findLabel(north.org.id, target.id);
    expect(after).toEqual(before);
    expect(after?.description).toBe("keep me");
  });

  it("returns zero when nothing carried the source", async () => {
    const { source, target } = await seedPair(north, "empty");
    const result = await labelService.mergeLabels(north.actors.owner, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });
    expect(result.issuesRelabelled).toBe(0);
    await expect(labelRepo.findLabel(north.org.id, source.id)).resolves.toBeNull();
  });

  it("leaves the other tenant's labels and issues alone", async () => {
    const acmeSource = await labelService.createLabel(acme.actors.admin, {
      orgId: acme.org.id,
      name: "happy-source",
      color: "#ff0000",
      description: null,
    });
    const acmeTarget = await labelService.createLabel(acme.actors.admin, {
      orgId: acme.org.id,
      name: "happy-target",
      color: "#00ff00",
      description: null,
    });
    const acmeIssue = await makeIssue(acme, "acme issue", [acmeSource.id]);

    const { source, target } = await seedPair(north, "isolated");
    await makeIssue(north, "north issue", [source.id]);

    await labelService.mergeLabels(north.actors.admin, {
      orgId: north.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    });

    expect(labelIdsOnIssue(acmeIssue.id)).toEqual([acmeSource.id]);
    await expect(labelRepo.findLabel(acme.org.id, acmeSource.id)).resolves.not.toBeNull();
    await expect(labelRepo.findLabel(acme.org.id, acmeTarget.id)).resolves.not.toBeNull();
  });
});

describe("mergeLabels guards", () => {
  it("rejects a member, who lacks project:archive, and changes nothing", async () => {
    const { source, target } = await seedPair(north, "denied");
    const issue = await makeIssue(north, "denied issue", [source.id]);

    await expect(
      labelService.mergeLabels(north.actors.member, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(labelIdsOnIssue(issue.id)).toEqual([source.id]);
    await expect(labelRepo.findLabel(north.org.id, source.id)).resolves.not.toBeNull();
  });

  it("rejects an input whose orgId is not the actor's organization", async () => {
    const { source, target } = await seedPair(north, "tenant");
    const issue = await makeIssue(north, "tenant issue", [source.id]);

    await expect(
      labelService.mergeLabels(north.actors.owner, {
        orgId: acme.org.id,
        sourceLabelId: source.id,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(labelIdsOnIssue(issue.id)).toEqual([source.id]);
  });

  it("reports not-found for an unknown source and changes nothing", async () => {
    const { target } = await seedPair(north, "unknown-src");
    const issue = await makeIssue(north, "unknown src issue", [target.id]);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: UNKNOWN_LABEL,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(labelIdsOnIssue(issue.id)).toEqual([target.id]);
  });

  it("reports not-found for a target that belongs to another organization", async () => {
    const { source } = await seedPair(north, "cross-tgt");
    const foreignTarget = await labelService.createLabel(acme.actors.admin, {
      orgId: acme.org.id,
      name: "cross-foreign-target",
      color: "#123456",
      description: null,
    });
    const issue = await makeIssue(north, "cross target issue", [source.id]);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: foreignTarget.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(labelIdsOnIssue(issue.id)).toEqual([source.id]);
    await expect(labelRepo.findLabel(north.org.id, source.id)).resolves.not.toBeNull();
    await expect(labelRepo.findLabel(acme.org.id, foreignTarget.id)).resolves.not.toBeNull();
  });

  it("reports not-found for a source that belongs to another organization", async () => {
    const { target } = await seedPair(north, "cross-src");
    const foreignSource = await labelService.createLabel(acme.actors.admin, {
      orgId: acme.org.id,
      name: "cross-foreign-source",
      color: "#654321",
      description: null,
    });

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: foreignSource.id,
        targetLabelId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(labelRepo.findLabel(acme.org.id, foreignSource.id)).resolves.not.toBeNull();
  });

  it("rejects source === target when called directly, and changes nothing", async () => {
    const { source } = await seedPair(north, "self");
    const issue = await makeIssue(north, "self issue", [source.id]);

    await expect(
      labelService.mergeLabels(north.actors.admin, {
        orgId: north.org.id,
        sourceLabelId: source.id,
        targetLabelId: source.id,
      }),
    ).rejects.toThrow();

    expect(labelIdsOnIssue(issue.id)).toEqual([source.id]);
    await expect(labelRepo.findLabel(north.org.id, source.id)).resolves.not.toBeNull();
  });

  it("the repository refuses source === target too, and changes nothing", async () => {
    const { source } = await seedPair(north, "repo-self");
    const issue = await makeIssue(north, "repo self issue", [source.id]);

    await expect(
      labelRepo.mergeLabel(north.org.id, source.id, source.id),
    ).rejects.toThrow();

    expect(labelIdsOnIssue(issue.id)).toEqual([source.id]);
    expect(getDb().select().from(labels).where(eq(labels.id, source.id)).all()).toHaveLength(1);
  });
});

