/**
 * Folds `sourceLabelId` into `targetLabelId`. Every issue that carried the
 * source carries the target afterwards, exactly once, and the source row is
 * deleted. Archived issues are included because the join rows carry no
 * archive state of their own.
 *
 * Returns how many issues carried the source before the merge. Runs in one
 * transaction and throws before writing if either label is not in `orgId`.
 */
export async function mergeLabel(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const found = tx
      .select({ id: labels.id })
      .from(labels)
      .where(
        and(
          orgPredicate(labels.orgId, orgId),
          inArray(labels.id, [sourceLabelId, targetLabelId]),
        ),
      )
      .all();
    if (found.length !== 2) {
      throw new Error("Merging needs two distinct labels from this organization");
    }

    const carrying = tx
      .select({ value: count() })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .get();
    const issuesRelabelled = carrying?.value ?? 0;

    // An issue that already carries the target keeps that row and loses the
    // source one; relabelling it would violate the (issue, label) key.
    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
          inArray(
            issueLabels.issueId,
            tx
              .select({ issueId: issueLabels.issueId })
              .from(issueLabels)
              .where(
                and(
                  orgPredicate(issueLabels.orgId, orgId),
                  eq(issueLabels.labelId, targetLabelId),
                ),
              ),
          ),
        ),
      )
      .run();

    tx.update(issueLabels)
      .set({ labelId: targetLabelId })
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return issuesRelabelled;
  });
}

