/**
 * Label CRUD and the issue↔label assignment used by the picker.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope
 */
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as labelRepo from "@/server/repositories/label-repository";
import { orgResource, requireFound } from "./_support";
import type {
  CreateLabelInput,
  MergeLabelsInput,
  UpdateLabelInput,
} from "@/schemas/label";
import type { LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Labels are org-wide metadata, so they follow the project permissions. */
export async function listLabels(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:read", orgResource(orgId));
  return labelRepo.listLabels(orgId);
}

export async function createLabel(
  actor: Actor,
  input: CreateLabelInput,
): Promise<IssueLabel> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:update", orgResource(input.orgId));

  const existing = await labelRepo.listLabels(input.orgId);
  if (existing.some((label) => label.name === input.name)) {
    throw new Error(`A label named "${input.name}" already exists`);
  }

  return labelRepo.insertLabel(input);
}

export async function updateLabel(
  actor: Actor,
  input: UpdateLabelInput,
): Promise<IssueLabel> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:update", orgResource(input.orgId));
  return labelRepo.updateLabel(input);
}

/**
 * Deleting a label detaches it from every issue. That is a wider blast radius
 * than the other label writes, so it takes the archive permission.
 */
export async function deleteLabel(
  actor: Actor,
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:archive", orgResource(orgId));
  await labelRepo.deleteLabel(orgId, labelId);
}

/**
 * Relabels every issue that carries the source with the target, then removes
 * the source. The source disappears from every issue, so this takes the same
 * archive permission as `deleteLabel`.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  // The schema rejects this too. Checked again because a direct caller that
  // skipped the schema would otherwise delete the label it merges into.
  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("A label cannot be merged into itself");
  }

  requireFound(
    await labelRepo.findLabel(input.orgId, input.sourceLabelId),
    "Label",
    input.sourceLabelId,
  );
  const target = requireFound(
    await labelRepo.findLabel(input.orgId, input.targetLabelId),
    "Label",
    input.targetLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabel(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );

  return { label: target, issuesRelabelled };
}
